/// ureq 2 has no timeout error kind: connect and read deadlines surface as an
/// `io::ErrorKind::TimedOut` somewhere in the transport error's source chain.
fn is_timeout(transport: &ureq::Transport) -> bool {
    let mut source = std::error::Error::source(transport);
    while let Some(error) = source {
        if error
            .downcast_ref::<std::io::Error>()
            .is_some_and(|io| io.kind() == std::io::ErrorKind::TimedOut)
        {
            return true;
        }
        source = error.source();
    }
    false
}

fn assemble_raw(
    response: ureq::Response,
    elapsed: Duration,
    attempt: u32,
) -> Result<SdkRawResponse, SdkError> {
    let status_code = response.status();
    let status_text = response.status_text().to_string();
    let headers = flatten_headers(&response);
    let request_id = find_request_id(&headers);
    let mut buf = Vec::new();
    response.into_reader().read_to_end(&mut buf).map_err(|e| {
        SdkError::Network(SdkNetworkError {
            message: format!("read response: {}", e),
            request_id: request_id.clone(),
        })
    })?;
    Ok(SdkRawResponse {
        status_code,
        status_text,
        headers,
        body: buf,
        request_id,
        latency: elapsed,
        attempt,
    })
}

