/// Incremental Server-Sent Events framer. It owns the whole `field: value`
/// grammar so the blocking [`SdkStreamIter`] and the asynchronous event stream
/// frame identical events from the same bytes.
#[derive(Debug, Default)]
pub struct SseParser {
    data: Vec<String>,
    event: Option<String>,
    id: Option<String>,
    retry: Option<u32>,
}

impl SseParser {
    pub fn new() -> Self {
        Self::default()
    }

    /// Consumes one line, with or without its trailing newline. Returns the
    /// event when that line closes a block.
    pub fn push_line(&mut self, line: &str) -> Option<SdkStreamEvent> {
        let trimmed = line.trim_end_matches(['\r', '\n']);
        if trimmed.is_empty() {
            if self.data.is_empty() {
                self.event = None;
                return None;
            }
            return Some(self.take_event());
        }
        if trimmed.starts_with(':') {
            return None;
        }
        let (field, value) = match trimmed.find(':') {
            Some(idx) => {
                let f = &trimmed[..idx];
                let v = &trimmed[idx + 1..];
                (f, v.strip_prefix(' ').unwrap_or(v))
            }
            None => (trimmed, ""),
        };
        match field {
            "event" => self.event = Some(value.to_string()),
            "data" => self.data.push(value.to_string()),
            "id" => self.id = Some(value.to_string()),
            "retry" => self.retry = value.parse().ok(),
            _ => {}
        }
        None
    }

    /// Emits the trailing block when the connection closes without a final
    /// blank line.
    pub fn finish(&mut self) -> Option<SdkStreamEvent> {
        if self.data.is_empty() {
            None
        } else {
            Some(self.take_event())
        }
    }

    fn take_event(&mut self) -> SdkStreamEvent {
        SdkStreamEvent {
            event: self.event.take().unwrap_or_else(|| "message".to_string()),
            data: std::mem::take(&mut self.data).join("\n"),
            id: self.id.take(),
            retry: self.retry.take(),
        }
    }
}

/// Iterator over SSE events. Implements `Iterator<Item = Result<SdkStreamEvent, SdkError>>`.
pub struct SdkStreamIter {
    reader: BufReader<Box<dyn std::io::Read + Send + Sync>>,
    parser: SseParser,
    stream_format: String,
    chunk_domain: String,
    finished: bool,
}

impl Iterator for SdkStreamIter {
    type Item = Result<SdkStreamEvent, SdkError>;
    fn next(&mut self) -> Option<Self::Item> {
        if self.finished {
            return None;
        }
        if self.stream_format == "chunked" {
            let mut chunk = vec![0_u8; 8192];
            return match self.reader.read(&mut chunk) {
                Ok(0) => {
                    self.finished = true;
                    None
                }
                Ok(size) => {
                    chunk.truncate(size);
                    let data = if self.chunk_domain == "text" {
                        match String::from_utf8(chunk.clone()) {
                            Ok(value) => value,
                            Err(error) => {
                                return Some(Err(SdkError::Network(SdkNetworkError {
                                    message: format!("decode text chunk: {}", error),
                                    request_id: None,
                                })))
                            }
                        }
                    } else {
                        use base64::Engine as _;
                        base64::engine::general_purpose::STANDARD.encode(&chunk)
                    };
                    Some(Ok(SdkStreamEvent {
                        event: "chunk".to_string(),
                        data,
                        id: None,
                        retry: None,
                    }))
                }
                Err(error) => Some(Err(SdkError::Network(SdkNetworkError {
                    message: format!("stream read: {}", error),
                    request_id: None,
                }))),
            };
        }
        loop {
            let mut line = String::new();
            match self.reader.read_line(&mut line) {
                Ok(0) => {
                    self.finished = true;
                    return if self.stream_format == "ndjson" {
                        None
                    } else {
                        self.parser.finish().map(Ok)
                    };
                }
                Err(e) => {
                    return Some(Err(SdkError::Network(SdkNetworkError {
                        message: format!("stream read: {}", e),
                        request_id: None,
                    })))
                }
                Ok(_) => {
                    if self.stream_format == "ndjson" {
                        let data = json_record_text(&line);
                        if !data.is_empty() {
                            return Some(Ok(SdkStreamEvent {
                                event: "message".to_string(),
                                data: data.to_string(),
                                id: None,
                                retry: None,
                            }));
                        }
                        continue;
                    }
                    if let Some(event) = self.parser.push_line(&line) {
                        return Some(Ok(event));
                    }
                }
            }
        }
    }
}

/// Polls a long-running operation until it reaches a terminal state. The
/// caller supplies a poll function and a predicate that classifies each
/// result. Returns the final result, or `SdkError::Timeout` on deadline.
pub struct WaitForConfig {
    pub interval: Duration,
    pub max_interval: Duration,
    pub timeout: Duration,
}

impl Default for WaitForConfig {
    fn default() -> Self {
        Self {
            interval: Duration::from_secs(1),
            max_interval: Duration::from_secs(30),
            timeout: Duration::from_secs(600),
        }
    }
}

pub struct WaitForTerminal {
    pub done: bool,
    pub failed: bool,
    pub reason: Option<String>,
}

pub fn wait_for<T, F, G>(mut poll: F, is_terminal: G, config: WaitForConfig) -> Result<T, SdkError>
where
    F: FnMut() -> Result<T, SdkError>,
    G: Fn(&T) -> WaitForTerminal,
{
    let deadline = Instant::now() + config.timeout;
    let mut interval = config.interval;
    loop {
        let result = poll()?;
        let state = is_terminal(&result);
        if state.done {
            if state.failed {
                return Err(SdkError::Network(SdkNetworkError {
                    message: format!(
                        "operation failed: {}",
                        state.reason.unwrap_or_else(|| "unknown".to_string())
                    ),
                    request_id: None,
                }));
            }
            return Ok(result);
        }
        if Instant::now() >= deadline {
            return Err(SdkError::Timeout(SdkTimeoutError {
                elapsed: config.timeout,
                request_id: None,
            }));
        }
        let jitter =
            Duration::from_millis((rand_u32() as u64) % config.interval.as_millis() as u64);
        let wait = std::cmp::min(interval + jitter, config.max_interval);
        thread::sleep(wait);
        interval = std::cmp::min(interval * 2, config.max_interval);
    }
}
